from ads_src import A
A("us-kodak","Kodak (1889): 'You press the button, we do the rest'","US","ad","real_long","kodak",
 "\"You press the button, — we do the rest.\" … \"The only camera that anybody can use without instructions.\" … \"Send for the Primer, free.\" … \"Price $25.00 — Loaded for 100 Pictures.\"",
 "good","Removes the beginner's fear (effort), backs it with a specific claim, gives a free first step and a clear price. Kodak used the slogan for years.",
 [("Headline","Effort → almost zero.","—","Clinic: 'Du bokar – vi sköter resten.'"),("Hook","'anybody can use without instructions' — specific.","—","—"),
  ("Image","Hand holding the camera.","—","Show the one simple action."),("Offer","$25, 100 pictures — concrete.","—","Price + exactly what's included."),("CTA","'Send for the Primer, free.'","—","Free first step.")],img="kodak")
A("us-pepsodent","Pepsodent (1929): free 10-day tube","US","ad","real_long","pepsodent",
 "\"FREE… a 10-day tube to everyone who wants white, dazzling teeth\" … 'Film is found by dental research to discolor teeth…' … \"FREE—10-DAY TUBE. Mail coupon to…\"",
 "good","Hopkins-era sampling: offer-first headline, a named enemy ('film') as a mechanism, and a coupon so every ad could be measured.",
 [("Headline","Offer + reader desire.","—","'Gratis provvecka till alla som vill komma igång.'"),("Hook","Mechanism: 'film'.","—","Name the mechanism behind your result."),
  ("Image","Smiling woman + coupon.","—","—"),("Offer","Free 10-day tube.","—","—"),("CTA","Mail the coupon.","—","Track every response.")],img="pepsodent")
