A("wmf-5","Wikipedia banner (2010 test): 'If everyone reading this donated $5…'","Global","ad","real_tested","wmf_tests",
 "\"If everyone reading this donated $5, our fundraiser would end today. Please donate to keep Wikipedia free.\"",
 "good","Tested winner. Dec 28, 2010: 365 donations from 1,421,605 impressions vs 181 from 1,325,539 for 'Only 4 days left…'. A tiny, specific ask + a picture of the result.",
 [("Headline","Specific small number ($5).","—","'Svara ”ja” så har du rapporten inom 24 h.'"),("Hook","Imagine everyone doing it.","—","—"),
  ("Image","Text-only banner.","—","Plain can win."),("Offer","Ending the fundraiser.","—","—"),("CTA","Donate.","—","—")],img="wmf",metric="365/1,421,605 vs 181/1,325,539 donations/impressions (Wikimedia raw tables).")
A("wmf-4days","Wikipedia banner (2010 test): 'Only 4 days left…'","Global","ad","real_tested","wmf_tests",
 "\"Only 4 days left to make a tax deductible contribution to keep Wikipedia free. Please help Wikipedia pay its bills in 2011.\"",
 "bad","Tested loser against the $5 banner (181 vs 365 donations at similar impressions). Deadline pressure + an abstract reason ('pay its bills') was weaker than a specific small ask. 'Bad' = weaker in the test.",
 [("Headline","A deadline.","Pressure without a picture of the outcome.","Use a small specific ask instead."),("Hook","—","'pay its bills' is abstract.","Show the result."),
  ("Image","Text-only.","—","—"),("Offer","Tax deduction.","Not why most people give.","—"),("CTA","Help.","Vague.","Name the amount.")],img="wmf",metric="181/1,325,539 vs 365/1,421,605 (lost).")
